SELECT 

FROM project_planning
WHERE 1=1

    AND project_id = #{param.projectId}


    AND planning_no LIKE CONCAT('%', #{param.planningNo}, '%')


    AND planning_name LIKE CONCAT('%', #{param.planningName}, '%')


    AND planning_type = #{param.planningType}



    AND planning_status = #{param.planningStatus}


    AND planning_status = #{param.planningStatus}


    AND responsible_person_id = #{param.responsiblePersonId}


    AND responsible_person_name LIKE CONCAT('%', #{param.responsiblePersonName}, '%')


    AND approver_id = #{param.reviewerId}


    AND approver_name LIKE CONCAT('%', #{param.reviewerName}, '%')


    AND budget_amount >= #{param.minBudgetAmount}


    AND budget_amount <= #{param.maxBudgetAmount}


    AND planned_start_date >= #{param.plannedStartDateBegin}


    AND planned_start_date <= #{param.plannedStartDateEnd}


    AND planned_end_date >= #{param.plannedEndDateBegin}


    AND planned_end_date <= #{param.plannedEndDateEnd}


    AND actual_start_date >= #{param.actualStartDateBegin}


    AND actual_start_date <= #{param.actualStartDateEnd}


    AND actual_end_date >= #{param.actualEndDateBegin}


    AND actual_end_date <= #{param.actualEndDateEnd}


    AND approval_date >= #{param.reviewTimeBegin}


    AND approval_date <= #{param.reviewTimeEnd}


    AND create_time >= #{param.createTimeBegin}


    AND create_time <= #{param.createTimeEnd}


    AND create_by = #{param.createBy}


    AND (planning_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR planning_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR planning_description LIKE CONCAT('%', #{param.keyword}, '%')
         OR responsible_person_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR planning_objectives LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COUNT(1)
FROM project_planning
WHERE planning_no = #{planningNo}

    AND id != #{excludeId}

