mapper.select:
SELECT
FROM project_planning WHERE planning_no LIKE CONCAT('%', #{keyword}, '%') OR planning_name LIKE CONCAT('%', #{keyword}, '%') OR planning_description LIKE CONCAT('%', #{keyword}, '%') OR responsible_person_name LIKE CONCAT('%', #{keyword}, '%') OR planning_objectives LIKE CONCAT('%', #{keyword}, '%') ORDER BY create_time DESC
LIMIT #{limit}

SELECT
    planning_status as planningStatus,
    COUNT(*) as count,
    COALESCE(SUM(budget_amount), 0) as totalBudget,
    COALESCE(SUM(actual_cost), 0) as totalActualCost,
    COALESCE(AVG(budget_amount), 0) as avgBudget
FROM project_planning
WHERE 1=1

    AND project_id = #{param.projectId}


    AND planning_type = #{param.planningType}


    AND responsible_person_id = #{param.responsiblePersonId}


    AND create_time >= #{param.createTimeBegin}


    AND create_time <= #{param.createTimeEnd}

GROUP BY planning_status
ORDER BY planning_status
